// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber) public {
        vm.assume(blockNumber > 0);

        // Record the block number using vm.roll
        vm.roll(blockNumber);

        // Give the contract some initial balance
        vm.deal(address(c), 100 ether);

        // Fund the caller
        address caller = address(0x1234);
        vm.deal(caller, 10 ether);

        // Call fallback with 10 ether
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");

        if (success) {
            uint256 balance = address(c).balance;
            if (blockNumber % 15 == 0) {
                assertTrue(balance == 0, "Balance should be zero when block.number % 15 == 0");
            } else {
                assertTrue(balance > 0, "Balance should be non-zero when block.number % 15 != 0");
            }
        }
    }
}

